import { CompanyHierarchyContent } from '@/company-management/components';
import { useCompanyHierarchy } from '@/company-management/hooks/useCompanyHierarchy';
import {
  CompanyHierarchyProps,
  CompanyHierarchyViewMode,
} from '@/company-management/types';
import {
  IllustratedMessage,
  ProgressSpinner,
} from '@adobe-commerce/elsie/components';
import { Container } from '@adobe-commerce/elsie/lib';
import { useText } from 'preact-i18n';

export const CompanyHierarchy: Container<CompanyHierarchyProps> = ({
  className,
  withHeader = false,
  slots,
  defaultExpanded = true,
  showAdminBadge = false,
}) => {
  const translations = useText({
    containerTitle: 'Company.CompanyHierarchy.containerTitle',
    noAccessTitle: 'Company.CompanyHierarchy.noAccess.title',
    noAccessMessage: 'Company.CompanyHierarchy.noAccess.message',
    expandAll: 'Company.CompanyStructure.shared.buttons.expandAll',
    collapseAll: 'Company.CompanyStructure.shared.buttons.collapseAll',
    expandAllNodes: 'Company.CompanyStructure.shared.ariaLabels.expandAllNodes',
    collapseAllNodes:
      'Company.CompanyStructure.shared.ariaLabels.collapseAllNodes',
    expand: 'Company.CompanyStructure.shared.options.expand',
    collapse: 'Company.CompanyStructure.shared.options.collapse',
    noCompaniesData: 'Company.CompanyHierarchy.messages.noCompaniesData',
    loading: 'Company.CompanyHierarchy.messages.loading',
    loadError: 'Company.CompanyHierarchy.messages.loadError',
    moveError: 'Company.CompanyHierarchy.messages.moveError',
  });
  const {
    treeItems,
    viewMode,
    onMove,
    expandedIds,
    setExpandedIds,
    selectedId,
    setSelectedId,
    expandAll,
    collapseAll,
    canDrop,
    errorMessage,
  } = useCompanyHierarchy(defaultExpanded);

  switch (viewMode) {
    case CompanyHierarchyViewMode.IS_LOADING:
      return (
        <div className="company-hierarchy-loading">
          <IllustratedMessage message={<ProgressSpinner size="large" />} />
        </div>
      );
    case CompanyHierarchyViewMode.IS_EMPTY:
      return (
        <div className="company-hierarchy-empty">
          <IllustratedMessage heading={translations.noCompaniesData} />
        </div>
      );
    case CompanyHierarchyViewMode.IS_ERROR:
      return (
        <div className="company-hierarchy-error">
          <IllustratedMessage
            heading={errorMessage || translations.loadError}
          />
        </div>
      );
    case CompanyHierarchyViewMode.NO_ACCESS:
      return (
        <div className="company-hierarchy-no-access">
          <IllustratedMessage heading={translations.noAccessMessage} />
        </div>
      );
    case CompanyHierarchyViewMode.SHOW_STRUCTURE:
      return (
        <CompanyHierarchyContent
          className={className}
          withHeader={withHeader}
          errorMessage={errorMessage}
          treeItems={treeItems}
          onMove={onMove}
          expandedIds={expandedIds}
          setExpandedIds={setExpandedIds}
          selectedId={selectedId}
          setSelectedId={setSelectedId}
          expandAll={expandAll}
          collapseAll={collapseAll}
          canDrop={canDrop}
          slots={slots}
          showAdminBadge={showAdminBadge}
          translations={{
            expandAll: translations.expandAll,
            collapseAll: translations.collapseAll,
            expandAllNodes: translations.expandAllNodes,
            collapseAllNodes: translations.collapseAllNodes,
            expand: translations.expand,
            collapse: translations.collapse,
            noCompaniesData: translations.noCompaniesData,
            containerTitle: translations.containerTitle,
            moveError: translations.moveError,
          }}
        />
      );
    default:
      return null;
  }
};
